// Presentation only: preserve native Database forms, values and submission.
define("theme_inzhe/catalogue", ['core/str'], function(Str) {
    'use strict';
    return {init: function() {
        if (document.body.id !== 'page-mod-data-view') {
            return;
        }
        document.querySelectorAll('.inzhe-book__tags > span').forEach(function(container) {
            const tags = container.textContent.split(/[,;\n]+/).map(function(tag) {
                return tag.trim();
            }).filter(Boolean);
            const fragment = document.createDocumentFragment();
            tags.forEach(function(tag) {
                const chip = document.createElement('span');
                chip.textContent = tag;
                fragment.appendChild(chip);
            });
            container.replaceWith(fragment);
        });
        Str.get_string('search').then(function(label) {
            document.querySelectorAll('#options input[type="submit"]:not([name="resetadv"])').forEach(function(submit) {
                submit.value = label;
            });
        }).catch(function() { /* Retain Moodle's native label if strings are unavailable. */ });
    }};
});
